style.css:
@namespace url(http://www.w3.org/1999/xhtml);

* {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif !important;
  color: #e0d6ff !important;
  text-shadow: 0 0 4px #8f00ff77 !important;
  border-color: #8f00ff55 !important;
}

body, html {
  background-color: #0a0a0a !important;
}

a, a:visited {
  color: #b383ff !important;
}

input, textarea, select, button {
  background-color: #1a1a1a !important;
  color: #e0d6ff !important;
  border: 1px solid #8f00ff55 !important;
  box-shadow: 0 0 6px #8f00ff33 !important;
}

div, section, article, header, footer, main, aside {
  background-color: rgba(26, 26, 26, 0.9) !important;
  border-radius: 10px !important;
  box-shadow: 0 0 10px #8f00ff22 !important;
}
